// Writes an integer with digit grouping.
template <typename OutputIt, typename UInt, typename Char>
auto write_int(OutputIt out, UInt value, unsigned prefix,
               const format_specs<Char>& specs,
               const digit_grouping<Char>& grouping) -> OutputIt {
  static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");

  bool upper = specs.type == presentation_type::hex_upper ||
               specs.type == presentation_type::bin_upper;
  unsigned base_bits =
      specs.type == presentation_type::hex_lower ||
              specs.type == presentation_type::hex_upper
          ? 4
          : specs.type == presentation_type::bin_lower ||
                    specs.type == presentation_type::bin_upper
                ? 1
                : specs.type == presentation_type::oct ? 3 : 0;

  int num_digits;
  char digits[128];
  if (base_bits != 0) {
    num_digits = base_bits == 1   ? count_digits<1>(value)
                 : base_bits == 3 ? count_digits<3>(value)
                                  : count_digits<4>(value);
    if (value == 0) {
      digits[0] = '0';
    } else {
      const char* digit_chars = upper ? "0123456789ABCDEF" : "0123456789abcdef";
      UInt remaining = value;
      char* digit_ptr = digits + num_digits;
      while (remaining != 0) {
        unsigned digit = static_cast<unsigned>(remaining) &
                         ((1u << base_bits) - 1);
        *--digit_ptr = static_cast<char>(base_bits < 4
                                             ? static_cast<char>('0' + digit)
                                             : digit_chars[digit]);
        remaining >>= base_bits;
      }
    }
  } else if (value == 0) {
    num_digits = 1;
  } else if (value < 10) {
    num_digits = 1;
  } else if (value < 100) {
    num_digits = 2;
  } else if (value < 1000) {
    num_digits = 3;
  } else if (value < 10000) {
    num_digits = 4;
  } else if (value < 100000) {
    num_digits = 5;
  } else if (value < 1000000) {
    num_digits = 6;
  } else if (value < 10000000) {
    num_digits = 7;
  } else if (value < 100000000) {
    num_digits = 8;
  } else if (value < 1000000000) {
    num_digits = 9;
  } else {
    num_digits = 9;
    UInt high_part = value / 1000000000u;
    while (high_part >= 100000000) {
      high_part /= 100000000u;
      num_digits += 8;
    }
    if (high_part >= 10000000) {
      num_digits += 8;
    } else if (high_part >= 1000000) {
      num_digits += 7;
    } else if (high_part >= 100000) {
      num_digits += 6;
    } else if (high_part >= 10000) {
      num_digits += 5;
    } else if (high_part >= 1000) {
      num_digits += 4;
    } else if (high_part >= 100) {
      num_digits += 3;
    } else if (high_part >= 10) {
      num_digits += 2;
    } else {
      num_digits += 1;
    }
  }

  char digits[40];
  UInt remaining = value;
  char* digit_ptr = digits + num_digits;
  if (remaining == 0) {
    digits[0] = '0';
  } else {
    while (remaining >= 10000) {
      unsigned chunk = static_cast<unsigned>(remaining % 10000);
      remaining /= 10000;
      unsigned lo = chunk % 100;
      unsigned hi = chunk / 100;
      digit_ptr -= 2;
      const char* lo_digits = digits2(static_cast<size_t>(lo));
      digit_ptr[0] = lo_digits[0];
      digit_ptr[1] = lo_digits[1];
      digit_ptr -= 2;
      const char* hi_digits = digits2(static_cast<size_t>(hi));
      digit_ptr[0] = hi_digits[0];
      digit_ptr[1] = hi_digits[1];
    }
    while (remaining >= 100) {
      unsigned pair = static_cast<unsigned>(remaining % 100);
      remaining /= 100;
      digit_ptr -= 2;
      const char* pair_digits = digits2(static_cast<size_t>(pair));
      digit_ptr[0] = pair_digits[0];
      digit_ptr[1] = pair_digits[1];
    }
    if (remaining < 10) {
      *--digit_ptr = static_cast<char>('0' + static_cast<int>(remaining));
    } else {
      digit_ptr -= 2;
      const char* pair = digits2(static_cast<size_t>(remaining));
      digit_ptr[0] = pair[0];
      digit_ptr[1] = pair[1];
    }
  }

  const char* digit_chars = digits;
  unsigned prefix_size = prefix != 0 ? 1u : 0u;

  int separators[64];
  int separator_count = 0;
  int sep_n = 1;
  separators[0] = 0;

