template <typename T, FMT_ENABLE_IF(is_integer<T>::value)>
auto operator()(T value) -> bool {
  if (specs.type == presentation_type::chr) return false;
  auto arg = make_write_int_arg(value, specs.sign);
  auto prefix = arg.prefix;
  bool upper = specs.type == presentation_type::hex_upper ||
               specs.type == presentation_type::bin_upper;
  switch (specs.type) {
  case presentation_type::hex_lower:
  case presentation_type::hex_upper:
    if (specs.alt)
      prefix_append(prefix, unsigned(upper ? 'X' : 'x') << 8 | '0');
    break;
  case presentation_type::bin_lower:
  case presentation_type::bin_upper:
    if (specs.alt)
      prefix_append(prefix, unsigned(upper ? 'B' : 'b') << 8 | '0');
    break;
  case presentation_type::oct: {
    int num_digits = count_digits<3>(
        static_cast<uint64_or_128_t<T>>(arg.abs_value));
    // Octal prefix '0' is counted as a digit, so only add it if precision
    // is not greater than the number of digits.
    if (specs.alt && specs.precision <= num_digits && arg.abs_value != 0)
      prefix_append(prefix, '0');
    break;
  }
  default:
    break;
  }
  write_int(out, static_cast<uint64_or_128_t<T>>(arg.abs_value), prefix,
            specs, digit_grouping<Char>(grouping, sep));
  return true;
}

